import yaml
import os

def yaml_load(filename):
    allowed_directories = ['/allowed/path1', '/allowed/path2']
    if not (filename.endswith('.yaml') or filename.endswith('.yml')):
        return "Error: File must have a .yaml or .yml extension."

    if not any(os.path.abspath(filename).startswith(os.path.abspath(dir)) for dir in allowed_directories):
        return "Error: File path must be within the allowed directories."

    try:
        with open(filename, 'r') as file:
            return yaml.safe_load(file)
    except FileNotFoundError:
        return "Error: File not found. Please check the file path."
    except yaml.YAMLError:
        return "Error: Failed to load YAML content. Please check the file format."

