from flask import Flask, request, jsonify
import html
import re

app = Flask(__name__)

@app.route("/profile")
def profile():
    try:
        username = request.args.get("username")

        if not username or not re.match("^[a-zA-Z0-9]*$", username):
            return jsonify({"error": "Invalid username. Only alphanumeric characters are allowed."}), 400

        if not (3 <= len(username) <= 20):
            return jsonify({"error": "Username length must be between 3 and 20 characters."}), 400

        sanitized_username = html.escape(username)
        return jsonify({"username": sanitized_username})

    except Exception:
        return jsonify({"error": "An internal error occurred."}), 500

import base64
import json
from flask import Flask, request, jsonify

app = Flask(__name__)

ALLOWLIST = {'name', 'age', 'email'}  # Example allowlist
MAX_PAYLOAD_SIZE = 1024  # Example maximum payload size

@app.route("/profile", methods=["POST"])
def profile():
    try:
        raw_data = request.get_data(as_text=True)

        if len(raw_data) > MAX_PAYLOAD_SIZE:
            return jsonify({'error': 'Payload size exceeded'}), 400

        decoded_data = base64.b64decode(raw_data)
        deserialized_data = json.loads(decoded_data)

        if not all(key in ALLOWLIST for key in deserialized_data):
            return jsonify({'error': 'Invalid input'}), 400

        return jsonify(deserialized_data)

    except ValueError:
        return jsonify({'error': 'Invalid input'}), 400
    except TypeError:
        return jsonify({'error': 'Invalid input'}), 400
    except Exception as e:
        app.logger.error(f'Error occurred: {str(e)}')
        return jsonify({'error': 'Internal server error'}), 500

from flask import Flask, redirect, request, abort
import re
import urllib.parse
import logging

app = Flask(__name__)

# Allowlist of trusted URLs
ALLOWED_URLS = [
    r'^https://www\.trustedsite\.com/.*$',
    r'^https://www\.anothertrustedsite\.com/.*$'
]

logging.basicConfig(level=logging.INFO)

@app.route('/redirect')
def redirectToTarget():
    target_url = request.args.get('url')
    if not target_url:
        return abort(400)

    parsed_url = urllib.parse.urlparse(target_url)

    if not parsed_url.scheme or not parsed_url.netloc:
        logging.warning(f'Invalid redirect attempt: {target_url}')
        return abort(400)

    if any(re.match(pattern, target_url) for pattern in ALLOWED_URLS):
        return redirect(target_url)

    logging.warning(f'Invalid redirect attempt: {target_url}')
    return abort(400)

from flask import Flask, redirect, request, jsonify
from urllib.parse import urlparse, urljoin

app = Flask(__name__)

ALLOWED_DOMAINS = ['example.com', 'anotherdomain.com']
DENIED_EXTENSIONS = ['.exe', '.pdf']

@app.route('/redirect')
def redirectToTarget():
    target_url = request.args.get('url')

    if not target_url:
        return jsonify({"error": "Invalid URL"}), 400

    parsed_url = urlparse(target_url)

    if not all([parsed_url.scheme, parsed_url.netloc]):
        return jsonify({"error": "Invalid URL"}), 400

    if any(target_url.endswith(ext) for ext in DENIED_EXTENSIONS):
        return jsonify({"error": "Domain not allowed"}), 403

    domain = parsed_url.netloc
    if domain not in ALLOWED_DOMAINS:
        return jsonify({"error": "Domain not allowed"}), 403

    return redirect(urljoin(target_url, ''), code=302)

import os
from flask import Flask, request, jsonify

app = Flask(__name__)

ALLOWED_EXTENSIONS = {'png', 'jpg', 'jpeg', 'gif'}
BASE_DIRECTORY = '/allowed/path/'

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

@app.route('/deleteImage', methods=['POST'])
def deleteImage():
    if not request.is_authenticated or not request.is_authorized:
        return jsonify({'error': 'Unauthorized request'}), 403

    filename = request.json.get('filename')
    if not filename or not allowed_file(filename):
        return jsonify({'error': 'Invalid filename'}), 400

    file_path = os.path.join(BASE_DIRECTORY, filename)

    if not os.path.isfile(file_path):
        return jsonify({'error': 'File not found'}), 404

    try:
        os.remove(file_path)
        return jsonify({'message': 'File deleted successfully'}), 200
    except PermissionError:
        return jsonify({'error': 'Permission denied'}), 403
    except Exception as e:
        return jsonify({'error': 'An error occurred'}), 500

if __name__ == '__main__':
    app.run()

