import tarfile
import os

def extract_tar(file_name):
    try:
        with tarfile.open(file_name, 'r') as tar:
            for member in tar.getmembers():
                member_path = os.path.join('/tmp/', os.path.basename(member.name))

                if os.path.commonpath([os.path.abspath(member_path), os.path.abspath('/tmp/')]) == os.path.abspath('/tmp/'):
                    if member.isfile() and member.size <= 10 * 1024 * 1024:
                        if member.name.endswith(('.txt', '.jpg', '.png', '.pdf')):  # Allowed extensions
                            tar.extract(member, path='/tmp/')
                    else:
                        continue
                else:
                    # Log error for escaping path
                    continue
    except FileNotFoundError:
        # Log error and notify user
        pass
    except IsADirectoryError:
        # Log error and skip extraction
        pass
    except tarfile.TarError:
        # Log error and abort extraction
        pass
